/* Attach files at creation as well as from any open task; retain all versions. */
(()=>{'use strict';const shared=document.body.classList.contains('shared-app'),q=s=>document.querySelector(s),notify=s=>(shared?message:toast)(s);
function validate(files){if(files.length>10||files.some(f=>!f.size||f.size>20*1048576)||files.reduce((n,f)=>n+f.size,0)>50*1048576)throw Error('حداکثر ۱۰ فایل؛ هر فایل ۲۰ و مجموعاً ۵۰ مگابایت. فایل خالی قابل ثبت نیست.')}
function decorate(form){if(!form||form.querySelector('#creationFiles'))return;const box=document.createElement('section');box.className='creation-attachments';box.innerHTML='<label>پیوست کار (اختیاری)<input id="creationFiles" type="file" multiple></label><label>عنوان نسخه<input id="creationFileLabel" maxlength="120" placeholder="مثلاً فایل اولیه یا اصلاحات مدیریت"></label><small>PDF، اکسل، ورد، عکس و سایر فایل‌ها؛ هر فایل حداکثر ۲۰ مگابایت.</small>';form.querySelector('button[type="submit"],button.primary')?.before(box);if(form.dataset.attachmentBound)return;form.dataset.attachmentBound='true';const submit=form.onsubmit;form.onsubmit=async e=>{e.preventDefault();const files=[...(form.querySelector('#creationFiles')?.files||[])],label=form.querySelector('#creationFileLabel')?.value||'';try{validate(files)}catch(err){return notify(err.message)}const before=new Set(tasks.map(t=>t.id));await submit(e);if(!files.length)return;let t=tasks.find(t=>!before.has(t.id));if(!t)return;let completed=0;try{if(shared){if(busy)return;busy=true;for(const file of files){message('در حال ثبت پیوست: '+file.name);const f=await rpc('sm_reserve_file',{p_task:t.id,p_revision:t.revision,p_name:file.name,p_size:file.size,p_type:file.type||'application/octet-stream',p_label:label});await checked(db.storage.from('samandis-files').upload(f.object_path,file,{contentType:file.type||'application/octet-stream',upsert:false}));await rpc('sm_finalize_file',{p_file:f.id});completed++;t=await checked(db.from('sm_tasks').select('*').eq('id',t.id).single())}await refresh()}else{await addTaskVersion(t,files,label);completed=files.length}await detail(t.id,true);notify('کار و '+completed.toLocaleString('fa-IR')+' فایل ثبت شدند.'+(form.dataset.assignmentFailed?' همکاران ذخیره نشدند؛ از ویرایش همکاران دوباره انتخاب کنید.':''))}catch(err){notify('کار ثبت شده؛ '+completed.toLocaleString('fa-IR')+' فایل ذخیره شد. ادامه بارگذاری را از فایل‌های همین کار انجام دهید. '+(shared?failure(err):err.message))}finally{if(shared)busy=false}}}
if(shared){const old=createTaskForm;createTaskForm=function(...args){old(...args);decorate(q('#newSharedTask'))}}else{const old=openSimpleEditor;openSimpleEditor=function(t=null){old(t);if(!t)decorate(q('#taskForm'));else q('#taskForm .creation-attachments')?.remove()}}
})();
